const archive="Cet article évite volontairement de reproduire des vidéos volées, des fichiers privés ou des affirmations techniques invérifiées. Lorsque l'événement touche à une fuite ou à une rumeur, le récit privilégie les reportages publics, les réponses officielles et les conséquences sur le chemin de la sortie. Pour un événement officiel, la source primaire de Rockstar ou de l'éditeur est présentée en premier. Cela permet aux archives de rester utiles après le lancement, lorsque les souvenirs émotionnels seront plus faciles à mélanger que les documents eux-mêmes.";
function render(record){const d=record;const when=d.when;const dateExpr=d.when.startsWith("vers ")?d.when:/^\d/.test(d.when)?"le "+d.when:"en "+d.when;const looking=`Vu depuis octobre 2026, « ${d.name} » est plus facile à replacer dans la chronologie qu'au moment des faits. Les bandes-annonces, profils officiels et reportages ultérieurs donnent un contexte que les fans ne possédaient pas ${dateExpr}. Ce recul est utile, mais peut aussi fausser les souvenirs en faisant paraître inévitables des indices alors incertains. The Final Wait préserve donc une photographie du moment : ce qu'on pouvait raisonnablement savoir, ce qui a été confirmé ensuite et pourquoi cet épisode compte encore sur la route du 19 novembre.`;
const next=`L'étape suivante documentée est ${d.next} (${d.nextWhen}). Aucune étape n'existait isolément : chacune changeait les questions posées à la suivante. Ce qui paraissait décisif un jour pouvait être précisé, retardé, reconsidéré ou dépassé par de nouveaux éléments officiels. Lire la chronologie dans l'ordre restitue ce mouvement et évite de déformer le passé avec le recul, en montrant comment la compréhension du public s'est construite progressivement plutôt qu'en sautant d'un indice précoce à la campagne finale.`;
const end=`Si vous ne deviez retenir qu'une chose de « ${d.name} », pensez à la place qu'il occupe dans l'histoire de l'attente, plutôt qu'à une image ou une citation isolée. ${/^\d/.test(d.when)?"Le ":"En "}${when}, la perception publique de GTA VI a de nouveau évolué : un fait est devenu officiel, un indice a trouvé son contexte ou la distance au lancement a paru plus mesurable. C'est cette succession que les archives cherchent à préserver. Le jeu terminé rendra certaines controverses d'avant-sortie secondaires, mais l'attente, l'incertitude, la surprise et les confirmations appartiennent aussi à l'histoire culturelle d'une sortie aussi importante. Conserver les sources auprès des souvenirs évite de transformer des hypothèses en faits.`;
if(d.future){
 const prospective="Depuis octobre 2026, « "+d.name+" » est encore une étape future. Les dates annoncées permettent de comprendre sa place dans la chronologie, mais non de raconter son déroulement comme un fait accompli. The Final Wait préserve cette distinction entre ce que Rockstar a annoncé et ce que les joueurs pourront vérifier lors de la sortie.";
 const futureEnd="Le "+d.when+" reste une date annoncée. Cette étape figure dans l'attente de GTA VI parce qu'elle marque un rendez-vous à venir, et non un événement déjà vécu. Une fois le moment arrivé, les faits vérifiés pourront être distingués des prévisions ; jusque-là, conserver les sources avec la mémoire de l'attente évite de prendre l'avenir pour le passé.";
 return [d.dek,d.dek+" "+intro,titles[0],d.what,titles[1],d.context,titles[2],d.why,titles[3],d.caution,titles[4],prospective,d.reflection,titles[5],fans[d.fan],titles[6],d.nextText||next,titles[7],archive,titles[8],futureEnd];
}
return [d.dek,d.dek+" "+intro,titles[0],d.what,titles[1],d.context,titles[2],d.why,titles[3],d.caution,titles[4],looking,d.reflection,titles[5],fans[d.fan],titles[6],next,titles[7],archive,titles[8],end];}
